"""Small HTTP client for the order service: token refresh, rate-limit waits, retries."""
import json
import os
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
WORK = "/tmp/recon"
LOG = os.path.join(WORK, "events.log")


def log(msg):
    os.makedirs(WORK, exist_ok=True)
    with open(LOG, "a") as f:
        f.write(f"{time.strftime('%H:%M:%S')} {msg}\n")


class Halt(Exception):
    """The service did something this client does not understand; stop and look."""


def retry_wait(headers, body):
    """Seconds the service asks us to wait, or None if it does not say."""
    ra = headers.get("Retry-After")
    if ra is not None:
        try:
            return float(ra)
        except ValueError:
            pass
    try:
        data = json.loads(body)
    except ValueError:
        return None
    if isinstance(data, dict):
        for key in ("retry_after", "retry_after_seconds", "wait", "wait_seconds"):
            if key in data:
                return float(data[key])
        for key in ("retry_after_ms", "wait_ms"):
            if key in data:
                return float(data[key]) / 1000.0
    return None


class Client:
    def __init__(self):
        self.token = None
        self.n_requests = 0
        self.n_tokens = 0
        self.n_429 = 0
        self.n_auth_fail = 0
        self.n_other_fail = 0

    def _send(self, method, path, auth):
        headers = {}
        if auth:
            headers["Authorization"] = f"Bearer {self.token}"
        data = b"" if method == "POST" else None
        req = urllib.request.Request(BASE + path, data=data, method=method, headers=headers)
        self.n_requests += 1
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status, r.headers, r.read()
        except urllib.error.HTTPError as e:
            return e.code, e.headers, e.read()

    def refresh(self):
        data = self.get_json("/token", auth=False, method="POST")
        self.token = data["token"]
        self.n_tokens += 1
        log(f"new token {self.token}")

    def get_json(self, path, auth=True, method="GET", allow_404=False):
        """Return parsed JSON for a 200. Return None for a confirmed 404 when allow_404."""
        attempts = 0
        not_found = 0
        while True:
            attempts += 1
            if attempts > 60:
                raise Halt(f"gave up on {path} after {attempts - 1} attempts")
            if auth and self.token is None:
                self.refresh()
            try:
                status, headers, body = self._send(method, path, auth)
            except (urllib.error.URLError, OSError) as e:
                log(f"{path}: connection problem {e!r}; retrying")
                time.sleep(1)
                continue

            if status == 200:
                try:
                    return json.loads(body)
                except ValueError:
                    log(f"{path}: HTTP 200 but body is not JSON: {body[:200]!r}; retrying")
                    self.n_other_fail += 1
                    continue

            text = body[:300].decode("utf-8", "replace")
            log(f"{path}: HTTP {status} headers={dict(headers)} body={text!r}")

            if status == 429:
                self.n_429 += 1
                wait = retry_wait(headers, body)
                if wait is None:
                    raise Halt(f"429 with no wait time on {path}: {dict(headers)} {text}")
                log(f"rate limited; waiting {wait}s as instructed")
                time.sleep(wait + 0.05)
                continue
            if status in (401, 403):
                self.n_auth_fail += 1
                self.token = None
                continue
            if status == 404 and allow_404:
                not_found += 1
                if not_found >= 3:
                    return None
                time.sleep(0.5)
                continue
            if status >= 500:
                self.n_other_fail += 1
                time.sleep(min(attempts, 5))
                continue
            raise Halt(f"unexpected HTTP {status} on {path}: {text}")

    def summary(self):
        return (f"requests={self.n_requests} tokens={self.n_tokens} 429s={self.n_429} "
                f"auth_failures={self.n_auth_fail} other_failures={self.n_other_fail}")

